package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the {@code householdSize} to a newly built owner: the number of owners that share the
 * same {@code householdId} once this owner is included. Runs after {@link AssignHousehold} (which
 * stamps and back-fills the household id) and before the owner is saved, so the count reflects the
 * household as it stands after this create. When the owner joined no household ({@code householdId}
 * is null) the household is just this owner, so the size is 1.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            owner.setHouseholdSize(1);
            return;
        }
        int count = 1; // the owner being created is not yet persisted
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                count++;
            }
        }
        owner.setHouseholdSize(count);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps the deterministic {@code householdId} onto a newly built owner. The id is a pure function
 * of the owner's last name and postcode (see {@link OwnerHousehold#id}), so it is always assigned -
 * owners with the same last name and postcode converge on the same value automatically, with no
 * lookup or coordination. Runs after {@link BuildOwner}, so the built owner (with its normalized
 * fields) is available to stamp, and before the household-duplicate check and identity check, which
 * both key off the finalized id.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerHousehold.id(owner.getLastName(), owner.getPostcode()));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.regex.Pattern;

/**
 * Shared household rules for the create-owner pipeline. The household identifier is now
 * <em>deterministic</em>: it is derived from the owner's last name and postcode alone, so any two
 * owners with the same (normalized) last name and the same postcode resolve to the same id without
 * coordination. Concretely the id is the first 12 hex characters of {@code SHA-256} over
 * {@code normalizedLastName + '|' + postcode}. Because the id is a pure function of those two
 * fields, sharing a household is no longer something a request opts into to create a link - it
 * happens automatically. The {@code sharesHousehold} flag now only bypasses the household-duplicate
 * block (see {@link CheckOwnerHouseholdUnique}).
 */
final class OwnerHousehold {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private OwnerHousehold() {
    }

    /** Canonical form of a last name for household keying: trimmed, whitespace-collapsed, lower-cased. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase();
    }

    /**
     * Deterministic identifier for the household of the given last name and postcode: the first 12
     * hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}. A null postcode
     * contributes an empty segment, so owners with the same last name and no postcode still share.
     */
    static String id(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        return sha256hex(key).substring(0, 12);
    }

    private static String sha256hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }
}

